 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the large rectangular 1-colored panel as its largest 4-connected component.
    seen = set()
    best = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(comp) > len(best):
                best = comp
    r0, r1 = min(r for r,c in best), max(r for r,c in best)
    c0, c1 = min(c for r,c in best), max(c for r,c in best)
    a, b = r1-r0+1, c1-c0+1
    panel = [row[c0:c1+1] for row in grid[r0:r1+1]]

    # Three external colored corner keys prescribe where the panel's matching
    # internal corner keys should land. Compare their corner arrangement to the
    # dihedral symmetries of the panel.
    external = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 1) and not (r0 <= r <= r1 and c0 <= c <= c1):
                external.setdefault(v, []).append((r,c))
    keys = {v for v in external if len(external[v]) == 1}
    inner = {}
    for r in range(a):
        for c in range(b):
            v = panel[r][c]
            if v in keys:
                inner[v] = (r,c)
    if len(inner) >= 3 and len(keys) >= 3:
        pts = [p[0] for v,p in external.items() if v in inner and len(p)==1]
        er0, er1 = min(y for y,x in pts), max(y for y,x in pts)
        ec0, ec1 = min(x for y,x in pts), max(x for y,x in pts)
        def corner(pos, hh, ww):
            r,c = pos
            return ('T' if r < hh/2 else 'B') + ('L' if c < ww/2 else 'R')
        targets = {}
        for v in inner:
            y,x = external[v][0]
            targets[v] = corner((y-er0,x-ec0), er1-er0+1, ec1-ec0+1)
        # Each formula returns a transformed coordinate and transformed size.
        maps = [
            (lambda r,c:(r,c), a,b),
            (lambda r,c:(b-1-c,r), b,a),
            (lambda r,c:(a-1-r,b-1-c), a,b),
            (lambda r,c:(c,a-1-r), b,a),
            (lambda r,c:(r,b-1-c), a,b),
            (lambda r,c:(a-1-r,c), a,b),
            (lambda r,c:(c,r), b,a),
            (lambda r,c:(b-1-c,a-1-r), b,a),
        ]
        for fn, oh, ow in maps:
            good = True
            for v,(r,c) in inner.items():
                rr,cc = fn(r,c)
                actual = corner((rr,cc),oh,ow)
                if actual != targets[v]:
                    good = False; break
            if good:
                out = [[0]*ow for _ in range(oh)]
                for r in range(a):
                    for c in range(b):
                        rr,cc = fn(r,c)
                        out[rr][cc] = panel[r][c]
                return out
    return panel
